const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app'),statusEl=document.querySelector('#status');let dash=null,view=new URLSearchParams(location.search).get('view')||'Recommended';
const VIEWS=['Recommended','New','Apply Now','Prepare','Watching','Applied','Rejected','Accepted','Skipped','Expired','All'];
const money=v=>v===null||v===undefined?'Unknown':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const tag=(s)=>`<span class="tag ${s==='REVIEW'?'review':['APPLY NOW','PREPARE','ACCEPTED','Won','Accepted'].includes(s)?'good':['REJECTED','Rejected','EXPIRED','SKIP'].includes(s)?'faded':['Applied','ALREADY APPLIED'].includes(s)?'':s==='CLOSING'?'urgent':''}">${E(s)}</span>`;
const score=(d)=>d.fit_score===null?`<span class="score">${E(d.analysis.scoring.lower_bound)}–${E(d.analysis.scoring.upper_bound)}<small>A Story fit · unresolved / 100<br>Range includes unknown points</small></span>`:`<span class="score">${E(d.fit_score)}<small>A Story fit / 100</small></span>`;
const deadlineLabel=value=>{if(!value)return 'Deadline unknown';if(/^\d{4}-\d{2}-\d{2}$/.test(value))return new Date(value+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});return readableDate(value);};
const date=d=>d.data.dates.deadline?E(deadlineLabel(d.data.dates.deadline))+'<br><small>'+(d.analysis.scoring.dates.days_remaining===null?'Time unverified':E(d.analysis.scoring.dates.days_remaining)+(d.analysis.scoring.dates.days_remaining===1?' day remaining':' days remaining'))+(d.analysis.scoring.dates.precision==='date_only'?' · Time unknown':'')+'</small>':'<span class="muted">Deadline unknown</span>';
const readableDate=v=>v?new Date(v).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'}):'Not yet verified';
const exactDate=v=>`<time datetime="${E(v||'')}" title="${E(v||'Unknown')}">${E(readableDate(v))}</time>`;
const benefitText=d=>d.data.funding.other_benefits||d.data.funding.award_scope||({credits_grant:'API credit grant',startup_support:'Startup support program',pitch_competition:'Pitch competition',grant:'Grant',accelerator:'Accelerator'}[d.data.opportunity_type])||d.data.opportunity_type.replaceAll('_',' ');
const benefits=d=>d.data.funding.cash_prize_max!==null?`${money(d.data.funding.cash_prize_max)}<br><small>${E(d.data.funding.award_scope||'Award terms require review')}</small>`:d.data.funding.credits_value!==null?`Up to ${money(d.data.funding.credits_value)}<br><small>Credits · tier-dependent</small>`:`<span class="benefit-description">${E(benefitText(d).slice(0,150))}</span><br><small>Usable value unknown</small>`;
const prettyKey=k=>k.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
function factsView(facts){return Object.keys(facts).length?Object.entries(facts).map(([key,f])=>`<div class="record"><strong>${E(prettyKey(key))}</strong><p>${E(Array.isArray(f.value)?f.value.join(', '):typeof f.value==='boolean'?(f.value?'Yes':'No'):f.value)}</p><small>Verified ${exactDate(f.last_verified)}</small></div>`).join(''):'<p class="muted">No structured eligibility facts are approved yet.</p>';}
function errorView(errors){return errors.length?errors.map(e=>`<div class="record"><strong>${E(prettyKey(e.state||'Research incomplete'))}</strong><p>${E(e.message||e)}</p><small>${E(e.program||'')} ${e.state==='ELIGIBILITY_UNKNOWN'?'Confirm company facts before relying on eligibility.':e.state==='SOURCE_UNAVAILABLE'?'The Hunter will retry verification on a later check.':''}</small></div>`).join(''):'<p>No research errors recorded.</p>';}
function usageView(usage){usage=usage||{};const tokens=usage.tokens||{};return `<p><strong>Research runner:</strong> ${usage.runner==='codex_chatgpt'?'Your existing ChatGPT sign-in':E(usage.research_runner||usage.runner||'Not recorded')}</p><p><strong>API key:</strong> ${usage.api_key_used===false?'Not used':'Not recorded'}</p><p><strong>Tokens:</strong> ${E(tokens.input_tokens??'Unknown')} input · ${E(tokens.output_tokens??'Unknown')} output</p><p><strong>API cost:</strong> ${usage.model_api_cost===null?'Not reported; this run uses your ChatGPT plan allowance':E(usage.model_api_cost??'Unknown')}</p>`;}
function proposalView(a){const p=a.proposal;return p?`<h2>${E(p.label)}</h2><p>${E(a.decision_needed)}</p><h3>Exact proposal</h3><p>${E(p.body)}</p><p><strong>Evidence status:</strong> ${E(p.evidence_status)} · Verified ${exactDate(p.last_verified_at)}</p><details><summary>Source and exact approval record</summary><p class="source-path">${E(p.original_path)}<br>${E(p.locator)}</p><pre>${E(JSON.stringify(JSON.parse(a.payload_json),null,2))}</pre></details>`:`<h2>${E(prettyKey(a.action))}</h2><p>${E(a.decision_needed)}</p><details><summary>Exact approval record</summary><pre>${E(JSON.stringify(JSON.parse(a.payload_json),null,2))}</pre></details>`;}

async function api(path,body){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
 try{const r=await fetch(path,{signal:controller.signal,...(body?{method:'POST',headers:{'Content-Type':'application/json','X-Founder-CSRF':document.querySelector('meta[name="founder-csrf"]').content},body:JSON.stringify(body)}:{})});
 if(!(r.headers.get('content-type')||'').includes('application/json'))throw new Error('Your sign-in expired or the server returned an unexpected page. Reload to sign in again.');
 const v=await r.json();if(!r.ok)throw new Error(v.error||'Unable to complete this action.');return v;
 }catch(e){if(e.name==='AbortError')throw new Error('The workspace took too long to respond. Try again.');if(e instanceof TypeError)throw new Error('The workspace is offline. Check that your PC is awake and online, then reload.');throw e;}finally{clearTimeout(timer);}
}
function toast(text,error=false){statusEl.innerHTML=`<div class="toast ${error?'error':''}">${E(text)}</div>`;statusEl.scrollIntoView({block:'nearest'});}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${E(title)}</h1><p class="muted">${E(subtitle)}</p></div>${action}</div>`;}
function rows(items){if(!items.length)return '<div class="empty">No opportunities match this view. Unknown eligibility stays in Review until the supporting company facts are confirmed.</div>';return `<div class="table-scroll"><table><thead><tr><th>Opportunity</th><th>Recommendation</th><th>A Story fit</th><th>Value</th><th>Deadline</th><th>Founder work</th></tr></thead><tbody>${items.map(d=>`<tr><td><a class="program-name" href="/opportunity/${E(d.opportunity_id)}">${E(d.data.canonical_name)}</a><br><small>${E(d.data.cycle)} · ${E(d.data.opportunity_type.replaceAll('_',' '))}<br>${d.verification_state==='VERIFIED'?'Official state verified':'Verification needed'} · ${exactDate(d.last_verified)}</small></td><td>${tag(d.recommendation)}<br><small>${E(d.analysis.eligibility.status)}</small></td><td>${d.fit_score===null?'<span class="score-unrated">Not rated</span><br><small>Eligibility / evidence incomplete</small>':score(d)}</td><td>${benefits(d)}</td><td>${date(d)}</td><td>${d.analysis.materials.estimated_hours===null?'Effort unknown':E(d.analysis.materials.estimated_hours)+' hours'}<br><small>${E(d.analysis.materials.effort)} · ${d.analysis.materials.percentage===null?'Requirements unknown':E(d.analysis.materials.percentage)+'% ready'}</small></td></tr>`).join('')}</tbody></table></div>`;}
function notice(){if(!dash)return '';const n=dash.company_memory.canonical_claims.length;return n===0?'<div class="notice"><strong>Company eligibility needs confirmation</strong><p>No company facts have been approved yet. The Hunter can verify programs, but A Story fit remains unresolved. <a href="/memory">Review company memory</a></p></div>':'';}
function activityList(runs){return runs.length?runs.map(r=>`<div class="record"><div class="section-title"><strong>Funding Hunter · ${E(r.state.toLowerCase())}</strong><a href="/run/${E(r.id)}">Open run report</a></div><small>Started ${exactDate(r.started_at)} · ${r.completed_at?'Completed '+exactDate(r.completed_at):'In progress'}</small><p class="inline-stat">${r.report.candidates_discovered||0} candidates · ${r.report.new_programs||0} new programs · ${r.report.verified||0} verified · ${r.report.duplicates_removed||0} duplicates · ${r.report.recommendations_generated||0} recommended · ${(r.report.errors||[]).length} errors</p></div>`).join(''):'<p class="empty">The first completed research run will appear here with its queries, sources and results.</p>';}
function briefRow(d){
 const b=d.analysis.founder_brief,m=d.analysis.materials,days=d.analysis.scoring.dates.days_remaining;
 return `<article class="opportunity-brief"><div class="section-title"><h3><a href="/opportunity/${E(d.opportunity_id)}">${E(d.data.canonical_name)}</a></h3>${tag(d.recommendation)}</div><p>${E(b.how_it_helps)}</p><div class="brief-meta"><span><strong>Deadline:</strong> ${E(deadlineLabel(d.data.dates.deadline))}${days!==null?' · '+E(days)+' days left':''}</span><span><strong>Effort:</strong> ${m.estimated_hours===null?'Needs estimate':E(m.estimated_hours)+' hours'}</span><span>${E(d.analysis.eligibility.status==='ELIGIBLE'?'Eligibility verified':'Eligibility still needs verification')}</span></div><p class="brief-action"><strong>Agent next:</strong> ${E(b.agent_next_step)}</p>${b.owner_decisions.length?`<p class="brief-action"><strong>Your decision:</strong> ${E(b.owner_decisions.join(' '))}</p>`:''}<a href="/opportunity/${E(d.opportunity_id)}">Review opportunity</a></article>`;
}
const PRIORITY_WORDS={CORE_PRODUCT:'Core product',COST_SAVINGS:'Cost savings',EXPLORATORY:'Exploratory'};
function closingWords(days,deadline){
 if(days===null||days===undefined)return deadline?'Closing time unverified':'No deadline published';
 if(days<0)return 'Closed';if(days===0)return 'Closes today';if(days===1)return 'Closes tomorrow';
 const day=new Date(/^\d{4}-\d{2}-\d{2}$/.test(deadline)?deadline+'T12:00:00':deadline).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/New_York'});
 return 'Closes in '+days+' days · '+day;
}
function moneyFigure(d){
 const m=d.analysis.money;
 if(m.cash_max)return `<span class="toc-figure">Up to ${money(m.cash_max)}</span>`;
 if(m.credits_face_value)return `<span class="toc-figure">Up to ${money(m.credits_face_value)} credits</span>`;
 return `<span class="toc-figure unknown">${m.kind==='CREDITS'?'Credit value unknown':'Amount unknown'}</span>`;
}
function tocRow(d,withWhy){
 const days=d.analysis.scoring.dates.days_remaining,m=d.analysis.money,b=d.analysis.founder_brief,closing=days!==null&&days>=0&&days<=7;
 const notes=[m.kind==='INVESTMENT'?'Investment, not a grant':'',d.analysis.eligibility.status==='ELIGIBLE'?'Eligible':'Eligibility unverified',b&&PRIORITY_WORDS[b.priority]&&m.kind==='CREDITS'?PRIORITY_WORDS[b.priority]:''].filter(Boolean);
 return `<li class="toc-row${closing?' closing':''}${days===null?' unknown-date':''}"><span class="toc-title"><a href="/opportunity/${E(d.opportunity_id)}">${E(d.data.canonical_name)}</a></span>${moneyFigure(d)}<span class="toc-meta"><span class="days${closing?' closing':''}"><span class="days-bar" data-days="${days===null?'':E(days)}"></span>${E(closingWords(days,d.data.dates.deadline))}</span>${notes.map(n=>`<span>${E(n)}</span>`).join('')}${tag(closing?'CLOSING':d.recommendation)}</span>${withWhy&&b?`<p class="toc-why">${E(b.how_it_helps)}</p>`:''}</li>`;
}
function paintDays(){document.querySelectorAll('.days-bar[data-days]').forEach(el=>{const v=el.dataset.days;if(v!=='')el.style.setProperty('--days-pct',String(Math.max(4,Math.min(100,100*Number(v)/60))));});}
async function home(){
 const board=dash.money_board,pitches=await api('/api/pitches').catch(()=>({items:[]}));
 const latestPitch=[...pitches.items].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0];
 const closingSoon=board.cash.filter(d=>{const n=d.analysis.scoring.dates.days_remaining;return n!==null&&n>=0&&n<=7;}).length;
 const today=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',timeZone:'America/New_York'});
 const lastRun=dash.agent_activity[0];
 app.innerHTML=heading('Today',today+'. What pays, what closes first, and what needs you.')+
 `<p class="state-line"><span><strong>${board.cash.length}</strong> cash programs open</span><span class="${closingSoon?'urgent':''}"><strong>${closingSoon}</strong> closing within a week</span><span><strong>${board.tracked.length}</strong> applied or decided</span><span><strong>${waitingCount()}</strong> waiting on you</span></p>`+
 `<div class="today"><div><section aria-labelledby="cash-title"><div class="block-title"><h2 id="cash-title">Cash on the table</h2><a href="/opportunities">Full pipeline</a></div><p class="block-note">Prizes, grants and fellowships, soonest deadline first. A pool size is not your award, and unknown amounts stay unknown until the agent verifies them.</p><ol class="toc">${board.cash.slice(0,8).map(d=>tocRow(d,true)).join('')||'<li class="empty">No open cash programs are verified right now. Run research to look for new competitions and grants.</li>'}</ol></section>`+
 `<section class="credits" aria-labelledby="credit-title"><div class="block-title"><h2 id="credit-title">Credits that cut real costs</h2></div><p class="block-note">Credits are not cash. Ranked by how directly they cover the voice and AI services A Story runs on.</p><ol class="toc">${board.credits.slice(0,6).map(d=>tocRow(d,false)).join('')||'<li class="empty">No open credit programs.</li>'}</ol></section></div>`+
 `<div class="side"><section class="section" aria-labelledby="wait-title"><h2 id="wait-title">Waiting on you</h2><p class="decide-count">${waitingCount()}</p><p class="small">${dash.inbox&&dash.inbox.proposed+dash.inbox.review?E(String(dash.inbox.proposed+dash.inbox.review))+' from your inboxes, plus c':'C'}ompany facts and pricing proposals. Until you approve them, the agents treat eligibility as unknown.</p><a class="button go primary" href="/decisions">Review proposals<span class="cap"><svg class="icon" aria-hidden="true"><use href="#i-arrow"/></svg></span></a></section>`+
 waitingSection(board.tracked)+
 (latestPitch?`<section class="section next-pitch" aria-labelledby="pitch-title"><h2 id="pitch-title">Latest pitch</h2><p><a href="/pitch/${E(latestPitch.pitch_id)}">${E(latestPitch.title)}</a></p><p class="small">${E(pitchLength(latestPitch.duration_seconds))} · ${E(latestPitch.audience)}</p><a class="button" href="/pitches">Pitch Studio</a></section>`:'')+
 `<section class="section" aria-labelledby="agent-title"><h2 id="agent-title">Agents</h2>${lastRun?`<p class="small">Last research ${E(lastRun.state.toLowerCase())} · ${exactDate(lastRun.completed_at||lastRun.started_at)} · ${lastRun.report.candidates_discovered||0} candidates checked</p>`:'<p class="small">No research run yet.</p>'}<p class="small">Daily report emails at 9 AM Eastern. Nothing is submitted without your confirmation of the exact filled form.</p><a href="/activity">All runs</a></section></div></div>`;
 paintDays();
}
function stageStrip(d){
 const outcome=(d.outcomes[0]||{}).outcome,stage=['Won','Accepted','Rejected','Withdrawn'].includes(outcome)?4:['Applied','Advanced','Finalist'].includes(outcome)?3:d.applications.length?2:1;
 return `<ol class="stages" aria-label="Application stage">${['Found','Preparing','Applied','Decided'].map((s,i)=>`<li class="${i+1<=stage?'reached':''}${i+1===stage?' current':''}"${i+1===stage?' aria-current="step"':''}>${s}${i+1===stage&&outcome?' · '+E(outcome):''}</li>`).join('')}</ol>`;
}
function notifications(){return dash.notifications.length?`<section class="section"><h2>Important findings</h2>${dash.notifications.map(n=>{const p=JSON.parse(n.payload_json);return `<div class="record"><strong>${E(n.kind.replaceAll('_',' '))}</strong><p><a href="/opportunity/${E(n.opportunity_id)}">${E(p.program)}</a> · ${p.fit_score===null?'Fit needs review':E(p.fit_score)+'/100'}</p><button data-action="read-notice" data-id="${E(n.id)}">Mark read</button></div>`;}).join('')}</section>`:'';}
async function opportunities(){app.innerHTML=heading('Funding pipeline','Every program the agents track: verified terms, current cycles, and the work left to apply.','<button class="primary" data-action="run">Run now</button>')+notice()+`<div class="tabs" role="group" aria-label="Opportunity views">${VIEWS.map(v=>`<button data-view="${E(v)}" class="${v===view?'active':''}">${E(v)}</button>`).join('')}</div><form id="filters" class="filters"><label>Minimum fit<input name="min_score" type="number" min="0" max="100" placeholder="Any"></label><label>Type<select name="type"><option value="">Any type</option>${[...new Set(['pitch_competition','grant','accelerator','incubator','startup_program','credits','credits_grant','fellowship','award',...dash.opportunities.map(d=>d.data.opportunity_type)])].map(v=>`<option value="${v}">${E(v.replaceAll('_',' '))}</option>`).join('')}</select></label><label>Effort<select name="effort"><option value="">Any effort</option>${['Very Low','Low','Medium','High','Very High','UNKNOWN'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Funding<select name="non_dilutive"><option value="">All terms</option><option value="1">Non-dilutive only</option></select></label><label>Minimum cash<input name="min_cash" type="number" min="0" placeholder="Any"></label><label>Location<input name="location" placeholder="e.g. Michigan"></label><label>Category<input name="category" placeholder="e.g. AI"></label><label>Deadline before<input name="deadline_before" type="date"></label><button type="submit">Filter</button></form><section class="section" id="opportunity-list"><p class="loading">Reading opportunities…</p></section>`;const q=new URLSearchParams(location.search);for(const [key,value]of q){const f=document.querySelector('#filters').elements[key];if(f)f.value=value;}await updateList();}
async function updateList(){const form=document.querySelector('#filters');const params=new URLSearchParams({view});for(const [k,v]of new FormData(form))if(v)params.set(k,v);const items=await api('/api/opportunities?'+params);history.replaceState(null,'','/opportunities?'+params);document.querySelector('#opportunity-list').innerHTML=rows(items);}
function materialList(label,items){return `<h3>${E(label)}</h3>${items.length?`<ul>${items.map(m=>`<li>${E(m.label)}${m.reason?`<br><small>${E(m.reason)}</small>`:''}</li>`).join('')}</ul>`:'<p class="small">None confirmed.</p>'}`;}
function creditConditions(d){
 const b=d.data.credit_benefits||{};if(!b.provider&&d.data.funding.credits_value===null)return '';
 const labels={provider:'Provider',tier:'Award tier',category:'Usage category',referral_required:'Referral required',company_email_required:'Company email required',paid_account_required:'Paid account required',deposit_required:'Deposit required',minimum_spend:'Minimum spend',expiration_months:'Expires after (months)',eligible_products:'Eligible products',excluded_products:'Excluded products',renewal_behavior:'After credits expire',stacking_restrictions:'Stacking restrictions',terms_acceptance_required:'Terms acceptance required'};
 return '<h2>Credits & conditions</h2><p class="small">'+E(d.analysis.credits?.cost_status||'Payment conditions need review')+'</p><dl>'+Object.entries(labels).map(([k,l])=>'<dt>'+E(l)+'</dt><dd>'+E(b[k]===null||b[k]===undefined?'Unknown':typeof b[k]==='boolean'?(b[k]?'Yes':'No'):b[k])+'</dd>').join('')+'</dl><p class="small">'+E(d.analysis.credits?.value_note||'Credits are restricted benefits, not cash.')+'</p>';
}
async function detail(id){const d=await api('/api/opportunity/'+encodeURIComponent(id));const a=d.analysis,m=a.materials;app.innerHTML=`<p><a href="/opportunities">← Funding pipeline</a></p>`+heading(d.data.canonical_name,d.data.cycle,tag(d.recommendation))+`<div class="lead-facts"><div>${score(d)}</div><div><strong>${d.data.funding.cash_prize_max!==null?money(d.data.funding.cash_prize_max):d.data.funding.credits_value!==null?'Up to '+money(d.data.funding.credits_value):'Value unknown'}</strong><small>${d.data.funding.credits_value!==null?'Credits, not cash':E(d.data.funding.award_scope||'Funding terms need verification')}</small></div><div><strong>${d.data.funding.equity_required===false?'Non-dilutive':d.data.funding.equity_required===true?'Equity / investment':'Equity terms unknown'}</strong><small>${E(d.data.funding.investment_terms||'')}</small></div><div>${date(d)}</div></div>${stageStrip(d)}<div class="actions"><button class="primary" data-action="prepare-pilot" data-id="${E(id)}">Start application</button><button data-action="research" data-id="${E(id)}">Research more</button>${d.recommendation==='ALREADY APPLIED'||d.outcomes.length?'':`<button data-outcome="Applied" data-opportunity="${E(id)}">Mark submitted</button>`}<button data-action="decision" data-decision="WATCH" data-id="${E(id)}">Watch</button><button data-action="decision" data-decision="SKIP" data-id="${E(id)}">Skip</button>${d.data.official_url?`<a class="button" href="${E(d.data.official_url)}" target="_blank" rel="noopener noreferrer">Official program ↗</a>`:''}</div><p class="small">Application Pilot prepares a draft. It emails the filled preview and waits for your confirmation before every submission. Unresolved facts, terms, account access and form checks appear under Applications.</p><div class="detail-grid"><div><section class="section">${creditConditions(d)}<h2>Why it may fit A Story</h2>${a.why_fit.length?`<ul>${a.why_fit.map(t=>`<li>${E(t)}</li>`).join('')}</ul>`:'<p>Fit requires verified program focus and approved company facts.</p>'}<h3>Why it may not fit</h3>${a.why_not_fit.length?`<ul>${a.why_not_fit.map(t=>`<li>${E(t)}</li>`).join('')}</ul>`:'<p class="muted">No additional limitation established yet.</p>'}${a.risks.length?`<h3>Risks</h3><ul>${a.risks.map(t=>`<li>${E(t)}</li>`).join('')}</ul>`:''}</section><section class="section"><h2>Eligibility</h2><p>${tag(a.eligibility.status)}</p><ul class="checks">${a.eligibility.checks.map(c=>`<li><span class="check ${c.result==='UNKNOWN'?'unknown':''}">${c.result==='PASS'?'Meets':c.result==='FAIL'?'Fails':'Unknown'}</span>${E(c.requirement)}<br><small>${E(c.result)} · <a href="${E(c.source_url)}" target="_blank" rel="noopener noreferrer">Source</a></small></li>`).join('')}</ul>${a.eligibility.missing.length?`<h3>Needs verification</h3><ul>${a.eligibility.missing.map(t=>`<li>${E(t)}</li>`).join('')}</ul>`:''}</section><section class="section"><h2>Sources & verification</h2><p class="small">${E(d.verification_state)} · Last verified ${exactDate(d.last_verified)}</p>${d.source_provenance.map(s=>`<div class="source"><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(new URL(s.url).hostname)} ↗</a><small> · ${E(s.role.replaceAll('_',' '))}</small><p>${E(s.excerpt)}</p><small>Checked ${exactDate(s.checked_at)}</small></div>`).join('')||'<p class="muted">Historical record; current official verification is pending.</p>'}<p>${E(d.data.notes)}</p></section><section class="section"><h2>Program history</h2>${d.history.map(h=>`<div class="record"><strong>${E(h.kind.replaceAll('_',' '))}</strong><p>${E(h.note)}</p><small>${E(h.original_path)} · ${E(h.locator)}</small></div>`).join('')||'<p class="muted">No migrated history for this program.</p>'}${d.outcomes.map(o=>`<p>${E(o.outcome)} · ${E(o.evidence_note)}</p>`).join('')}</section></div><div><section class="section"><h2>Application readiness</h2><strong>${m.percentage===null?'Requirements still unknown':E(m.percentage)+'% ready'}</strong>${m.percentage===null?'':`<progress class="progress" max="100" value="${m.percentage}" aria-label="Application material readiness"></progress>`}<p class="muted">${m.estimated_hours===null?'Time estimate pending':E(m.estimated_hours)+' estimated founder hours'} · ${E(m.effort)}</p>${materialList('Ready',m.ready)}${materialList('Needs adaptation',m.needs_adaptation)}${materialList('Missing',m.missing)}<p class="small">${E(m.estimate_basis)}</p></section><section class="section"><h2>Transparent fit score</h2>${Object.entries(a.scoring.components).map(([key,c])=>`<div class="score-row"><span>${E(key[0].toUpperCase()+key.slice(1))}<br><small>${E(c.reason)}</small></span><strong>${c.points===null?'?':E(c.points)}/${c.weight}</strong></div>`).join('')}<p class="small">Scoring ${E(a.scoring.version)} · ${E(a.scoring.coverage)}% evidence coverage. Unknown points remain a range.</p></section><section class="section"><h2>Your decision</h2><p>The agent recommends ${tag(d.recommendation)}. Record your choice and reason to improve future selection.</p><form id="decision-form" data-id="${E(id)}" class="decision"><label for="choice">Decision</label><select id="choice" name="decision"><option>APPLY</option><option>PREPARE</option><option>WATCH</option><option>SKIP</option></select><label for="reason">Reason</label><textarea id="reason" name="reason" required placeholder="What makes this worth the time—or not?"></textarea><button type="submit">Save decision</button></form>${d.decisions.map(c=>`<p class="small">${E(c.decision)} · ${E(c.reason)}</p>`).join('')}</section></div></div>`;}
function fallbackNote(auto){const m=(auto.report_schedule.hour??9)*60+(auto.report_schedule.minute??0)+(auto.mail_delivery.smtp_fallback.after_minutes??30),at=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');return ' If Codex has not sent by '+at+', the local Gmail fallback sends it once'+(auto.smtp_fallback_connected?'.':' after you run Connect-Report-Email.ps1.');}
async function activity(){app.innerHTML=heading('Agent activity','Queries, source checks, results, failures and retained run reports.')+`<section class="section">${activityList(dash.agent_activity)}</section>`;}
async function run(id){const r=await api('/api/run/'+encodeURIComponent(id));app.innerHTML='<p><a href="/activity">← Agent activity</a></p>'+heading('Funding Hunter run report',r.state)+`<section class="section"><p>${E(r.started_at)} → ${E(r.completed_at||'Running')}</p><div class="summary">${[['Candidates',r.report.candidates_discovered],['Verified',r.report.verified],['Created',r.report.records_created],['Duplicates',r.report.duplicates_removed]].map(([k,v])=>`<div><strong>${v||0}</strong><span>${k}</span></div>`).join('')}</div><h2>Queries used</h2><ul>${(r.report.queries_used||[]).map(q=>`<li>${E(typeof q==='string'?q:q.query)}</li>`).join('')}</ul><h2>Sources checked</h2><ul>${(r.report.sources_checked||[]).map(u=>`<li><a href="${E(u)}" target="_blank" rel="noopener noreferrer">${E(u)}</a></li>`).join('')}</ul><h2>Errors & incomplete research</h2>${errorView(r.report.errors||[])}<h2>Usage</h2>${usageView(r.report.usage||JSON.parse(r.usage_json||'{}'))}<details><summary>Exact run data</summary><pre>${E(JSON.stringify(r.report,null,2))}</pre></details></section>`;}
async function memory(){app.innerHTML=heading('Company facts','Current approved facts, with the proposals still waiting for you.')+notice()+`<section class="section"><div class="section-title"><h2>Approved company profile</h2><a href="/decisions">Review pending proposals</a></div><div class="memory-facts">${factsView(dash.company_memory.attributes)}</div><details><summary>Original approved records</summary>${dash.company_memory.canonical_claims.map(c=>`<div class="record"><strong>${E(c.label)}</strong><p class="source-path">${E(c.body)}</p></div>`).join('')}</details></section>`;}
function confirmationPreviews(confirmations){return confirmations.map(c=>{
 const p=JSON.parse(c.payload_json);return `<div class="record" id="${E(c.id)}"><div class="section-title"><h3>Filled application preview</h3>${tag(c.decision==='PENDING'?'Waiting for you':c.decision)}</div><p>${E(p.email)} · Preview email: ${E(c.email_state.replaceAll('_',' '))}</p><a href="${E(p.application_url)}" target="_blank" rel="noopener noreferrer">Official application</a><dl>${Object.entries(p.fields).map(([k,v])=>`<dt>${E(k)}</dt><dd>${E(v)}</dd>`).join('')}</dl><p class="small">No files, payments or terms acceptance. Changes to these fields or current company facts require a new preview.</p>${c.decision==='PENDING'?`<div class="actions"><button class="primary" data-action="confirm-application" data-id="${E(c.id)}" data-decision="APPROVED" ${c.email_state!=='SENT'?'disabled':''}>Confirm these fields and submit</button><button data-action="confirm-application" data-id="${E(c.id)}" data-decision="REJECTED" ${c.email_state!=='SENT'?'disabled':''}>Decline this application</button></div>`:''}</div>`;
 }).join('');}
async function applications(){
 const [items,auto]=await Promise.all([api('/api/applications'),api('/api/autonomy')]);
 const active=auto.authorizations.filter(a=>!a.revoked_at),pilot=active.some(a=>a.scope==='free_application_pilot');
 app.innerHTML=heading('Applications & daily reports','Prepare applications from current company truth. See what was sent and what needs your attention.')+notice()+
 `<section class="section"><div class="section-title"><h2>Application Pilot</h2>${tag(pilot?'Prepare, email, then wait for you':'Paused')}</div><p>Default email: <strong>gbao.n.vo@gmail.com</strong>. Company-required forms use <strong>bao@astoryapp.com</strong>.</p><p class="small">Every submission requires an emailed preview and your confirmation of the exact filled fields. Eligibility, current approved answers, zero fees, no deposits, no paid account activation, no unreviewed terms and a supported official form must also be verified. Login, CAPTCHA, file uploads and unfamiliar questions pause for review.</p>${pilot?active.filter(a=>a.scope==='free_application_pilot').map(a=>`<button data-action="pause-agent" data-id="${E(a.id)}">Pause application preparation</button>`).join(''):'<button data-action="resume-agent" data-scope="free_application_pilot">Resume application preparation</button>'}</section>`+
 `<section class="section"><div class="section-title"><h2>Daily email report</h2>${tag(auto.mail_connected?(auto.mail_delivery?.mode==='gmail_connector'?'Connected Gmail':'Mail connection saved'):'Gmail connection needed')}</div><p>Every day at ${E(String(auto.report_schedule.hour??9).padStart(2,'0'))}:${E(String(auto.report_schedule.minute??0).padStart(2,'0'))} Eastern to <strong>gbao.n.vo@gmail.com</strong>.</p><p>${auto.mail_connected?(auto.mail_delivery?.mode==='gmail_connector'?'The scheduled Gmail sender delivers the daily report and pending application previews, with recorded receipts.':'The sender will attempt today’s report and record Gmail acceptance.'):'Reports are saved here. No emails can be sent until you connect the local Gmail sender.'}</p><div class="actions">${auto.mail_connected?'':'<button class="primary" data-action="connect-mail">Connect report email</button>'}<button data-action="report-now">Prepare today’s report</button>${active.some(a=>a.scope==='daily_email_report')?active.filter(a=>a.scope==='daily_email_report').map(a=>`<button data-action="pause-agent" data-id="${E(a.id)}">Pause email reports</button>`).join(''):'<button data-action="resume-agent" data-scope="daily_email_report">Resume daily reports</button>'}</div><p class="small">${auto.mail_delivery?.mode==='gmail_connector'?'Gmail access stays with the connected plugin. Keep this PC awake, online and Codex running for scheduled email.'+(auto.mail_delivery?.smtp_fallback?.enabled?fallbackNote(auto):''):'Email connection details stay in Windows Credential Manager, outside this project. This PC must be awake, online and signed in.'} Your owner-only reports include a question-and-answer text preview. Every submission still needs your individual confirmation.</p>${auto.reports.map(r=>`<div class="record"><div class="section-title"><strong>${E(r.local_date)}</strong>${tag(r.state.replaceAll('_',' '))}</div><p>${E(r.error||'Saved report for '+r.recipient)}</p><button data-action="show-report" data-id="${E(r.id)}">Read report</button><div id="report-${E(r.id)}"></div></div>`).join('')}</section>`+
 `<section class="section"><div class="section-title"><h2>Application work</h2><a class="button" href="/api/review/export">Download all questions & draft answers</a></div>${confirmationPreviews(auto.confirmations)}${auto.plans.filter(p=>p.state!=='SUPERSEDED').map(p=>{const a=items.find(a=>a.id===p.application_id);return `<div class="record"><div class="section-title"><a class="program-name" href="/opportunity/${E(p.opportunity_id)}">${E(a?.program||'Application')}</a>${tag(p.state.replaceAll('_',' '))}</div><p>${E(p.selected_email)}</p>${p.blockers.length?`<details><summary>${p.blockers.length} items need attention</summary><ul>${p.blockers.map(b=>`<li>${E(b)}</li>`).join('')}</ul></details>`:'<p>All preparation checks passed.</p>'}<div class="actions"><a class="button" href="/application-review/${E(p.id)}">Questions & prepared answers</a><a class="button" href="/api/review/export?plan=${E(p.id)}">Download text preview</a><button data-action="prepare-pilot" data-id="${E(p.opportunity_id)}">Refresh application plan</button></div></div>`;}).join('')||'<p class="empty">Prepare an application from an opportunity to see its answers and blockers here.</p>'}</section>`+
 `<section class="section"><h2>Existing application records</h2>${items.map(a=>`<div class="record"><a class="program-name" href="/application/${E(a.id)}">${E(a.title)}</a><p>${E(a.program)} · ${E(a.cycle)} · ${tag(a.state)}</p><a href="/application/${E(a.id)}">Answers, copy and submission status</a></div>`).join('')||'<p class="empty">No application records yet.</p>'}</section>`;
}
const materialParams=new URLSearchParams(location.search);let materialQuery=materialParams.get('q')||'',materialKind=materialParams.get('kind')||'',materialCategory=materialParams.get('category')||'',materialOffset=Math.max(0,Number(materialParams.get('offset'))||0);
async function materials(){
 const params=new URLSearchParams({q:materialQuery,kind:materialKind,category:materialCategory,offset:materialOffset});const [lib,answers]=await Promise.all([api('/api/materials?'+params),api('/api/answers')]);history.replaceState(null,'','/materials?'+params);try{sessionStorage.setItem('astory-materials-list',location.pathname+location.search);}catch{}
 app.innerHTML=heading('Pitch materials','Search decks, essays, scripts and research. Originals remain in your folder.', '<a class="button" href="/api/materials-manifest">Download source manifest</a>')+
 `<section class="section"><p><strong>${lib.stats.total.toLocaleString()} source references</strong> · ${lib.stats.unique_files.toLocaleString()} distinct files · ${lib.stats.searchable_text||0} with searchable text</p><p class="small">Historical material is available for adaptation. It becomes current company truth only after review. Exact duplicate paths are grouped; generated previews are under Archived.</p>
 <form class="filters" id="material-filters"><label>Search materials<input name="q" value="${E(materialQuery)}" placeholder="Deck, grant, traction…"></label><label>Type<select name="kind"><option value="">All types</option>${lib.stats.kinds.map(k=>`<option value="${E(k.kind)}" ${k.kind===materialKind?'selected':''}>${E(prettyKey(k.kind))} (${k.count})</option>`).join('')}</select></label><label>Collection<select name="category">${[['','Useful materials'],['ARCHIVE','Archived / generated'],['all','All materials']].map(([v,l])=>`<option value="${v}" ${v===materialCategory?'selected':''}>${l}</option>`).join('')}</select></label><button type="submit">Search</button></form>
 <p class="small">${lib.total?materialOffset+1:0}–${Math.min(materialOffset+lib.limit,lib.total)} of ${lib.total} matching distinct files</p>
 ${lib.items.map(m=>`<div class="record"><div class="section-title"><a class="program-name" href="/material/${E(m.id)}">${E(m.relative_path.split(/[\\/]/).at(-1))}</a>${tag(prettyKey(m.kind))}</div><p class="source-path small">${E(m.relative_path)}</p><p class="small">${E(m.extraction==='reference_only'?'Original reference':m.extraction==='EXTRACTION_FAILED'?'Text extraction unavailable':'Text searchable')} · ${(m.size_bytes/1048576).toFixed(2)} MB${m.duplicates?' · '+m.duplicates+' duplicate paths':''} · ${E(m.category)}</p><div class="actions"><a class="button" href="/material/${E(m.id)}">Read material</a><a class="button" href="/api/material/${E(m.id)}/file">Download original</a></div></div>`).join('')||'<p class="empty">No materials match. Try a broader search or choose All materials.</p>'}
 <div class="actions"><button data-action="material-page" data-offset="${Math.max(0,materialOffset-lib.limit)}" ${materialOffset===0?'disabled':''}>Previous</button><button data-action="material-page" data-offset="${materialOffset+lib.limit}" ${materialOffset+lib.limit>=lib.total?'disabled':''}>Next</button></div></section>
 <section class="section"><h2>Saved answer versions</h2><p class="small">Drafts are not approved current answers or live form entries.</p>${answers.map(a=>`<details class="record"><summary>${E(a.prompt)} · ${E(a.status)}</summary>${answerBox(a.body,a.limit_value,a.limit_unit)}<small>${E(a.created_at)}</small></details>`).join('')}</section>`;
}
async function material(id){const m=await api('/api/material/'+encodeURIComponent(id));app.innerHTML=heading(m.relative_path.split(/[\\/]/).at(-1),'Source material · historical reference', '<a class="button" href="/materials">Back to materials</a>')+`<section class="section"><p>${tag(prettyKey(m.kind))} ${tag(m.category)} · ${(m.size_bytes/1048576).toFixed(2)} MB</p><p class="source-path">${E(m.source_path)}</p><p class="small source-path">Source version: ${E(m.source_version_id||'Binary reference only')}<br>Content hash: ${E(m.sha256||'Not freshly verified')}</p><div class="actions"><a class="button" href="/api/material/${E(id)}/file">Download original</a><a class="button" href="/pitches?material=${E(id)}">Adapt in Pitch Studio</a></div>${m.aliases.length?`<details class="record"><summary>${m.aliases.length} exact duplicate source paths</summary>${m.aliases.map(a=>`<p class="source-path small">${E(a.source_path)}</p>`).join('')}</details>`:''}</section><section class="section"><h2>Extracted text</h2><p class="small">Source text and notes are evidence for review; claims have not been promoted to company memory.</p>${m.body?`<pre class="report-copy">${E(m.body)}</pre>`:'<p class="empty">This file is registered as an original reference. Download it to view its images, slides or other content.</p>'}</section>`;}
async function applicationReview(id){const r=await api('/api/application-review/'+encodeURIComponent(id));app.innerHTML=heading('Questions & prepared answers',r.program+' · '+r.cycle,'<a class="button" href="/applications">Back to applications</a>')+`<section class="section"><p>${tag(r.state.replaceAll('_',' '))}</p><p>${E(r.submission_note)}</p><p class="source-path">${E(r.url||'Application URL unknown')}<br>${E(r.email)}</p><p class="small">Official form checked: ${E(r.form_checked_at||'Unknown')}</p><a class="button" href="/api/review/export?plan=${E(id)}">Download question & answer text</a></section><section class="section"><h2>Current official form</h2>${r.questions.length?r.questions.map((q,i)=>`<div class="record"><h3>${i+1}. ${E(q.question)}</h3><p>${tag(q.state)} · ${q.required?'Required':'Optional'} · ${q.limit?E(q.limit)+' characters':'Limit unknown'}</p>${q.answer===null?'<p class="answer-copy"><span class="muted">Blank. Needs an approved answer.</span></p>':answerBox(q.answer,q.limit,'characters')}<small>Field: ${E(q.field)} · Fact: ${E(q.fact_version||'none')} · Answer: ${E(q.answer_version||'none')}</small></div>`).join(''):'<p class="empty">Official questions are unknown. The form needs inspection, or it requires login or a dynamic form review. No answers have been filled for this form.</p>'}</section><section class="section"><h2>What needs attention</h2>${r.blockers.length?`<ul>${r.blockers.map(b=>`<li>${E(b)}</li>`).join('')}</ul>`:'<p>Preparation checks passed. An exact emailed preview and your individual confirmation are still required before submission.</p>'}</section>`;}
const OUTCOME_CHOICES=['Applied','Advanced','Finalist','Accepted','Rejected'];
function waitingCount(){return dash.needs_decision.length+(dash.inbox?dash.inbox.proposed+dash.inbox.review:0);}
function inboxAccounts(inbox){return `<ul class="tracker">${inbox.accounts.map(a=>`<li><span><strong>${E(a.account)}</strong><small class="tracker-sub">${a.connected?(a.last_checked?'Checked '+exactDate(a.last_checked):'Connected · first check within 5 minutes'):'Not connected'}${a.last_error?' · '+E(a.last_error):''}</small></span>${a.connected?tag('Read-only'):`<button data-action="connect-inbox" data-account="${E(a.account)}">Connect</button>`}</li>`).join('')}</ul>`;}
function inboxItem(m){return `<div class="decision"><div class="section-title"><h3>${E(m.program||'Unmatched email')}</h3>${tag(m.state==='PROPOSED'?m.proposed_outcome:'Review')}</div><p class="small">${E(m.sender)} to ${E(m.account)} · ${exactDate(m.received_at)}</p><p><strong>${E(m.subject)}</strong></p><p class="small">${E(m.snippet)}</p>${m.reason?`<p class="small">${E(m.reason)}</p>`:''}<div class="actions">${m.opportunity_id?`<label>Record as <select data-outcome-for="${E(m.id)}">${OUTCOME_CHOICES.map(o=>`<option${o===m.proposed_outcome?' selected':''}>${o}</option>`).join('')}</select></label><button class="primary" data-action="inbox-confirm" data-id="${E(m.id)}">Confirm</button>`:'<a class="button" href="/opportunities">Find the program</a>'}<button data-action="inbox-dismiss" data-id="${E(m.id)}">Not relevant</button></div></div>`;}
function inboxSection(inbox){if(!inbox)return '';return `<section class="section" aria-labelledby="inbox-title"><div class="section-title"><h2 id="inbox-title">From your inboxes</h2><a class="button" href="/api/tracker/export.csv">Export tracker (CSV)</a></div><p class="small">Founder OS reads these inboxes every 30 minutes, read-only, and proposes outcomes from program emails. Nothing is recorded until you confirm, and nothing in the mailbox is changed.</p>${inboxAccounts(inbox)}${inbox.pending.map(inboxItem).join('')||'<p class="empty">No new program emails to confirm.</p>'}</section>`;}
const KIND_WORDS={APPROVE:'Approve',CHECK:'Check it is still true',ANSWER:'Needs your answer',REMINDER:'Reminder'};
const factValue=v=>Array.isArray(v)?v.join(', '):typeof v==='boolean'?(v?'Yes':'No'):String(v);
function factCard(a){
 const c=a.card,reminder=c.kind==='REMINDER';
 return `<article class="fact-card kind-${E(c.kind.toLowerCase())}" id="card-${E(a.id)}"><div class="fact-head"><span class="fact-topic">${E(prettyKey(c.topic||'company'))} · ${E(c.label)}</span><span class="fact-kind">${E(KIND_WORDS[c.kind]||c.kind)}</span></div>`+
 `<p class="fact-sentence">${E(c.sentence)}</p><p class="fact-why">${E(c.why)}</p>`+
 (c.unlocks.length?`<p class="fact-line"><strong>Approving lets the agents check</strong> ${E(c.unlocks.join(', '))}.</p>`:'')+
 (c.replaces.length?`<p class="fact-line fact-replaces"><strong>Changes your current facts:</strong> ${c.replaces.map(r=>`${E(prettyKey(r.fact))} ${E(factValue(r.current))} → ${E(factValue(r.proposed))}`).join('; ')}</p>`:'')+
 (c.source?`<details class="fact-source"><summary>Where this came from</summary><p class="small source-path">${E(c.source)}${c.locator?'<br>'+E(c.locator):''}</p></details>`:'')+
 `<div class="actions">${reminder?`<button data-action="approve" data-id="${E(a.id)}" data-decision="rejected">Dismiss</button>`:`<button class="primary" data-action="approve" data-id="${E(a.id)}" data-decision="approved">Approve</button>${c.editable?`<button type="button" data-fact-edit="${E(a.id)}">Edit</button>`:''}<button data-action="approve" data-id="${E(a.id)}" data-decision="rejected">Reject</button>`}</div>`+
 (c.editable&&!reminder?`<form class="fact-edit" data-id="${E(a.id)}" hidden><label for="edit-${E(a.id)}">Write it the way it is true</label><textarea id="edit-${E(a.id)}" name="body" required>${E(c.sentence)}</textarea><div class="actions"><button class="primary" type="submit">Save and approve</button><button type="button" data-fact-edit="${E(a.id)}">Cancel</button></div></form>`:'')+
 `</article>`;
}
function recentDecisions(list){
 if(!list||!list.length)return '';
 return `<section class="decided" aria-labelledby="decided-title"><h2 id="decided-title">Recently decided</h2><ul class="tracker">${list.map(r=>`<li class="${r.state==='rejected'?'done':''}"><span><strong>${E(r.label)}</strong>${r.sentence&&!r.sentence.trim().startsWith('{')?`<small class="tracker-sub">${E(r.sentence)}</small>`:r.sentence?'<small class="tracker-sub">Company profile updated</small>':''}</span><span class="decided-meta">${tag(r.state==='approved'?'Approved':'Rejected')}<small>${E(new Date(r.decided_at).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/New_York'}))}</small></span></li>`).join('')}</ul></section>`;
}
async function decisions(){
 const cards=dash.needs_decision.filter(a=>a.card),open=cards.filter(a=>a.card.kind!=='REMINDER'),reminders=cards.filter(a=>a.card.kind==='REMINDER'),inboxWaiting=dash.inbox?dash.inbox.proposed+dash.inbox.review:0;
 app.innerHTML=heading('Decisions','Things only you can confirm. An approved fact is something the agents can rely on; nothing here is sent anywhere.')+
 `<p class="state-line"><span><strong>${open.length}</strong> facts to confirm</span><span><strong>${inboxWaiting}</strong> from your inboxes</span><span><strong>${reminders.length}</strong> reminders</span></p>`+
 `<section class="decision-group" aria-labelledby="facts-title"><div class="block-title"><h2 id="facts-title">Facts to confirm</h2></div>${open.map(factCard).join('')||'<p class="empty">Nothing to confirm. New facts from research, your notes or your inboxes will appear here.</p>'}</section>`+
 inboxSection(dash.inbox)+
 (reminders.length?`<section class="decision-group quiet" aria-labelledby="reminders-title"><div class="block-title"><h2 id="reminders-title">Reminders</h2></div><p class="block-note">Notes the agents keep in mind. They are not facts, so they can only be dismissed.</p>${reminders.map(factCard).join('')}</section>`:'')+
 recentDecisions(dash.recent_decisions);
}
document.addEventListener('click',e=>{
 const t=e.target.closest('[data-fact-edit]');if(!t)return;e.preventDefault();
 const form=document.querySelector(`form.fact-edit[data-id="${CSS.escape(t.dataset.factEdit)}"]`);if(!form)return;
 form.hidden=!form.hidden;if(!form.hidden){const ta=form.querySelector('textarea');ta.focus();ta.setSelectionRange(ta.value.length,ta.value.length);}
});
document.addEventListener('submit',async e=>{
 if(!e.target.classList.contains('fact-edit'))return;e.preventDefault();
 const body=new FormData(e.target).get('body'),btn=e.target.querySelector('button[type=submit]');
 if(!confirm('Save this wording as a confirmed company fact?'))return;btn.disabled=true;
 try{await api('/api/approval-edit',{approval_id:e.target.dataset.id,body,confirmed:true});await boot();toast('Saved your wording as a confirmed fact.');}catch(err){toast(err.message,true);}finally{btn.disabled=false;}
});
function routeContext(){
 const path=location.pathname,parent=path.startsWith('/pitch/')?'/pitches':path.startsWith('/material/')?'/materials':path.startsWith('/application-review/')||path.startsWith('/application/')?'/applications':path.startsWith('/opportunity/')?'/opportunities':path.startsWith('/run/')?'/activity':path;
 const names={'/':'Today','/pitches':'Pitch Studio','/materials':'Materials & answers','/applications':'Applications','/opportunities':'Funding pipeline','/activity':'Agent activity','/memory':'Company facts','/decisions':'Decisions'};
 document.querySelectorAll('#workspace-nav a').forEach(a=>{const active=a.getAttribute('href')===parent;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});
 document.querySelector('#breadcrumbs').innerHTML='<a href="/">A Story</a> / '+(parent!==path?'<a href="'+E(parent)+'">'+E(names[parent]||'Workspace')+'</a> / Detail':E(names[parent]||'Workspace'));
 document.querySelector('#workspace-location').textContent=location.hostname==='pitch.gbaonvo.com'?'Owner sign-in protected':'On this PC';document.title=(names[parent]||'Workspace')+' | A Story';
}
function applicationLayout(){
 const q=new URLSearchParams(location.search),view=['work','reports','settings'].includes(q.get('tab'))?q.get('tab'):'work',sections=[...app.querySelectorAll(':scope > .section')],heading=app.querySelector('.page-heading');
 const tabs=document.createElement('nav');tabs.className='workspace-tabs';tabs.setAttribute('aria-label','Application workspace');tabs.innerHTML=[['work','Application drafts'],['reports','Email reports'],['settings','Agent settings']].map(([key,title])=>'<a href="/applications?tab='+key+'" '+(view===key?'aria-current="page"':'')+'>'+title+'</a>').join('');heading.after(tabs);
 if(sections.length===4){sections[0].hidden=view!=='settings';sections[1].hidden=view!=='reports';sections[2].hidden=view!=='work';sections[3].hidden=view!=='work';if(view==='work'){tabs.after(sections[2]);sections[2].after(sections[3]);}}
 if(location.hash){const target=document.getElementById(location.hash.slice(1));if(target)target.scrollIntoView({block:'start'});}
}
async function boot(){
 routeContext();const path=location.pathname;
 if(path.startsWith('/pitch/'))return pitchEditor(path.split('/').at(-1));
 if(path==='/pitches')return pitchLibrary();
 if(path.startsWith('/material/')){await material(path.split('/').at(-1));try{app.querySelector('.page-heading a').href=sessionStorage.getItem('astory-materials-list')||'/materials';}catch{}return;}
 if(path==='/materials')return materials();
 if(path.startsWith('/application-review/'))return applicationReview(path.split('/').at(-1));
 if(path.startsWith('/application/'))return applicationPage(path.split('/').at(-1));
 if(path==='/applications'){await applications();applicationLayout();return;}
 dash=await api('/api/dashboard');
 const count=document.querySelector('#decision-count');if(count){count.textContent=waitingCount();count.hidden=!waitingCount();}
 if(path.startsWith('/opportunity/'))return detail(path.split('/').at(-1));
 if(path.startsWith('/run/'))return run(path.split('/').at(-1));
 return ({'/':home,'/opportunities':opportunities,'/activity':activity,'/memory':memory,'/decisions':decisions}[path]||home)();
}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.view){view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));return await updateList();}const action=b.dataset.action;if(!action)return;if(action==='reload'){location.reload();return;}b.disabled=true;if(action==='material-page'){materialOffset=Number(b.dataset.offset);await materials();window.scrollTo(0,0);}else if(action==='confirm-application'){if(confirm(b.dataset.decision==='APPROVED'?'Submit this exact emailed application preview?':'Decline this exact application preview?')){await api('/api/application-confirm',{confirmation_id:b.dataset.id,decision:b.dataset.decision,confirmed:true});await boot();toast('Your exact application decision is saved.');}}else if(action==='resume-agent'){if(confirm('Resume this previously authorized agent with the same limits?')){await api('/api/autonomy-resume',{scope:b.dataset.scope,confirmed:true});await boot();toast('Automatic action resumed with the existing limits.');}}else if(action==='inbox-confirm'){const outcome=document.querySelector(`[data-outcome-for="${b.dataset.id}"]`)?.value;if(confirm('Record this program as '+outcome+' from this email?')){await api('/api/inbox-decision',{id:b.dataset.id,decision:'confirm',outcome,confirmed:true});await boot();toast('Outcome recorded with the email as evidence.');}}else if(action==='inbox-dismiss'){await api('/api/inbox-decision',{id:b.dataset.id,decision:'dismiss',confirmed:true});await boot();toast('Email set aside. Nothing was recorded.');}else if(action==='connect-inbox'){await api('/api/connect-inbox',{account:b.dataset.account});toast('Secure inbox setup opened on this PC. Enter the Google app password there, never in chat.');}else if(action==='connect-mail'){await api('/api/connect-report-email',{});toast('Secure Gmail setup opened on this PC. Enter the Google app password there, never in chat.');}else if(action==='report-now'){await api('/api/report-now',{});await boot();toast('Today’s report is saved. The sender will use the connected mail account when available.');}else if(action==='show-report'){const r=await api('/api/report/'+encodeURIComponent(b.dataset.id));document.getElementById('report-'+b.dataset.id).innerHTML='<pre class="report-copy">'+E(r.body)+'</pre>'+r.attachments.map(a=>`<a class="button" href="/api/review-file/${E(a.artifact_id)}">Download question & answer attachment</a>`).join('');}else if(action==='pause-agent'){await api('/api/autonomy-pause',{authorization_id:b.dataset.id});await boot();toast('Automatic action paused.');}else if(action==='prepare-pilot'){await api('/api/prepare-application',{opportunity_id:b.dataset.id});if(location.pathname!=='/applications'){location.href='/applications';return;}await boot();toast('Application plan refreshed with current facts and blockers.');}else if(action==='run'){await api('/api/run-now',{});toast('Research request saved. The connected worker will run the scan and record its findings.');}else if(action==='research'){await api('/api/research',{opportunity_id:b.dataset.id});toast('Re-verification request saved for this opportunity.');}else if(action==='start'){const r=await api('/api/start-application',{opportunity_id:b.dataset.id});toast('Internal application draft is ready. No submission was sent.');}else if(action==='decision'){const reason=prompt('Reason for your '+b.dataset.decision.toLowerCase()+' decision:');if(reason){await api('/api/decision',{opportunity_id:b.dataset.id,decision:b.dataset.decision,reason});await boot();toast('Decision saved with the agent recommendation.');}}else if(action==='approve'){if(confirm('Confirm this exact '+b.dataset.decision+' decision after reviewing the proposal and evidence?')){await api('/api/approval',{approval_id:b.dataset.id,decision:b.dataset.decision,confirmed:true});await boot();toast('Owner decision recorded.');}}else if(action==='read-notice'){await api('/api/notification-read',{id:b.dataset.id});await boot();}}catch(err){toast(err.message,true);}finally{b.disabled=false;}});
document.addEventListener('submit',async e=>{if(!['material-filters','filters','decision-form'].includes(e.target.id))return;e.preventDefault();try{if(e.target.id==='material-filters'){const f=new FormData(e.target);materialQuery=f.get('q');materialKind=f.get('kind');materialCategory=f.get('category');materialOffset=0;return await materials();}if(e.target.id==='filters')return await updateList();if(e.target.id==='decision-form'){const f=new FormData(e.target);await api('/api/decision',{opportunity_id:e.target.dataset.id,decision:f.get('decision'),reason:f.get('reason')});await boot();toast('Decision saved. Scoring weights remain unchanged.');}}catch(err){toast(err.message,true);}});
document.querySelector('#nav-toggle').addEventListener('click',()=>{const nav=document.querySelector('#workspace-nav'),open=nav.classList.toggle('open');document.querySelector('#nav-toggle').setAttribute('aria-expanded',String(open));});
const countWords=t=>String(t||'').trim().split(/\s+/).filter(Boolean).length;
function countLabel(body,limit,unit){
 const isWords=unit!=='characters',n=isWords?countWords(body):String(body||'').length,over=limit&&n>limit;
 return `<span class="answer-count${over?' over':''}">${n}${limit?' / '+E(limit):''} ${isWords?'words':'characters'}${over?' · over limit':''}</span>`;
}
function answerBox(body,limit,unit){
 return `<div class="answer-box"><p class="answer-copy">${E(body)}</p><div class="answer-meta">${countLabel(body,limit,unit)}<button class="copy-button" type="button" data-copy="${E(body)}">Copy</button></div></div>`;
}
const RESULTS=['Advanced','Finalist','Won','Accepted','Rejected','Withdrawn'];
function waitingSection(tracked){
 const waiting=tracked.filter(t=>t.waiting),done=tracked.filter(t=>!t.waiting);
 const link=t=>t.application_id?'/application/'+t.application_id:'/opportunity/'+t.opportunity_id;
 const when=t=>new Date(t.occurred_at).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/New_York'});
 return `<section class="section" aria-labelledby="wait-results-title"><h2 id="wait-results-title">Waiting on results</h2>${waiting.length?`<ul class="tracker">${waiting.map(t=>`<li><span><a href="${E(link(t))}">${E(t.canonical_name)}</a><small class="tracker-sub">${E(t.outcome)} ${E(when(t))}${t.next_date?' · next: '+E(deadlineLabel(t.next_date)):' · next date not published'}</small></span>${tag(t.outcome)}</li>`).join('')}</ul>`:'<p class="small">Nothing pending. Mark an application submitted and it shows up here.</p>'}${done.length?`<h3 class="tracker-head">Decided</h3><ul class="tracker">${done.map(t=>`<li class="done"><a href="${E(link(t))}">${E(t.canonical_name)}</a>${tag(t.outcome)}</li>`).join('')}</ul>`:''}<p class="small"><a href="/api/tracker/export.csv">Export tracker (CSV)</a>${dash.inbox?' · '+(dash.inbox.accounts.some(a=>a.connected)?'Inboxes tracked read-only':'<a href="/decisions">Connect your inboxes</a>'):''}</p></section>`;
}
async function applicationPage(id){
 const a=await api('/api/application/'+encodeURIComponent(id)),latest=a.outcomes[0],submitted=a.outcomes.some(o=>o.outcome!=='Withdrawn');
 app.innerHTML=heading(a.program,a.cycle||'Application','<a class="button" href="/applications">Back to applications</a>')+
 `<section class="section application-status"><div class="section-title"><h2>Submission</h2>${latest?tag(latest.outcome):tag('Not submitted')}</div>${latest?`<p>${E(latest.outcome)} on ${exactDate(latest.occurred_at)}. ${E(latest.note)}</p>`:'<p>Paste the answers below into the official form. When you submit, mark it here so the agents stop recommending it.</p>'}<div class="actions">${a.application_url?`<a class="button" href="${E(a.application_url)}" target="_blank" rel="noopener noreferrer">Open the official form ↗</a>`:''}${submitted?'':`<button class="primary" data-outcome="Applied" data-opportunity="${E(a.opportunity_id)}" data-application="${E(a.id)}">Mark submitted</button>`}</div>`+
 (submitted?`<form id="outcome-form" class="result-form" data-opportunity="${E(a.opportunity_id)}" data-application="${E(a.id)}"><h3>Record a result</h3><div class="result-fields"><label>Result<select name="outcome">${RESULTS.map(r=>`<option>${r}</option>`).join('')}</select></label><label>Receipt or announcement link (optional)<input name="evidence_url" type="url" placeholder="https://"></label></div><label>Note<textarea name="note" placeholder="What happened, and anything worth remembering for next time"></textarea></label><button type="submit">Save result</button></form>`:'')+
 `${a.outcomes.length>1?`<details class="record"><summary>History (${a.outcomes.length})</summary>${a.outcomes.map(o=>`<p class="small">${E(o.outcome)} · ${exactDate(o.occurred_at)} · ${E(o.note)}</p>`).join('')}</details>`:''}</section>`+
 `<section class="section"><div class="section-title"><h2>Questions &amp; answers</h2><span class="small">${a.questions.length} saved</span></div>${a.questions.map(q=>`<div class="record"><h3>${E(q.prompt)}</h3>${q.answer?`<p class="small">${tag(q.answer.status==='approved'?'Approved':'Draft')} ${q.answer.provenance==='owner_written'?'· Your wording':''}</p>${answerBox(q.answer.body,q.limit,q.unit)}`:'<p class="muted">No answer saved yet.</p>'}</div>`).join('')||'<p class="empty">No questions saved for this application yet.</p>'}</section>`;
}
async function copyText(button){
 const text=button.dataset.copy;
 try{await navigator.clipboard.writeText(text);}catch{const t=document.createElement('textarea');t.value=text;t.setAttribute('readonly','');t.className='sr-only';document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();}
 const old=button.textContent;button.textContent='Copied';button.classList.add('copied');setTimeout(()=>{button.textContent=old;button.classList.remove('copied');},1600);
}
document.addEventListener('click',async e=>{
 const c=e.target.closest('[data-copy]');if(c){e.preventDefault();return copyText(c);}
 const o=e.target.closest('button[data-outcome]');if(!o)return;
 if(!confirm('Record that you submitted this application? The agents will stop recommending it.'))return;
 o.disabled=true;try{await api('/api/outcome',{opportunity_id:o.dataset.opportunity,outcome:o.dataset.outcome,application_id:o.dataset.application||null,note:'Owner marked submitted in Founder OS.'});await boot();toast('Marked submitted. It now appears under Waiting on results.');}catch(err){toast(err.message,true);}finally{o.disabled=false;}
});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='outcome-form')return;e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button[type=submit]');b.disabled=true;
 try{await api('/api/outcome',{opportunity_id:e.target.dataset.opportunity,application_id:e.target.dataset.application,outcome:f.get('outcome'),note:f.get('note')||'',evidence_url:f.get('evidence_url')||null});await boot();toast('Result saved.');}catch(err){toast(err.message,true);}finally{b.disabled=false;}
});
boot().catch(e=>{app.innerHTML='<section class="load-error">'+heading('Unable to open this page',e.message)+'<button data-action="reload">Reload workspace</button><p><a href="/pitches">Go to Pitch Studio</a></p></section>';});
